def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.25
        if hp <= 2 or no_water_days >= 1:
            safe_bid = DAILY_SALARY * 0.6
        return float(min(budget, safe_bid))

    prev_bids = []
    urgent_opponents = 0
    rich_live = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 200:
            rich_live += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    tightness = 1.0 - scarcity

    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1

    base = DAILY_SALARY * (0.34 + 0.22 * tightness)

    if highest_prev > 0:
        target = max(base, avg_prev * 0.72, highest_prev * 0.62)
    else:
        target = base

    if urgent_opponents >= 2:
        target += 8
    elif urgent_opponents == 1:
        target += 4

    if rich_live >= 2 and tightness > 0.5:
        target += 6

    if danger >= 3:
        target = max(target, highest_prev + 2.0, DAILY_SALARY * 0.95)
    elif danger == 2:
        target = max(target, highest_prev * 0.82, DAILY_SALARY * 0.78)
    elif danger == 1:
        target = max(target, highest_prev * 0.7, DAILY_SALARY * 0.62)

    if supply >= 23:
        target *= 0.82
    elif supply <= 17:
        target *= 1.12

    if day >= 8 and hp > 5 and no_water_days == 0:
        target *= 0.92

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 1.2
    max_affordable = max(0.0, budget - reserve)
    if danger >= 2:
        max_affordable = budget

    bid = min(target, max_affordable if max_affordable > 0 else budget)
    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids to infer how aggressive opponents are.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Supply pressure: if supply is near max, competition is lower; if near min, competition is higher.
    # Map supply in [15,25] to a multiplier in [1.15, 0.85]
    if MAX_SUPPLY != MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    supply_mult = 1.15 - 0.30 * float(t)

    # Core policy:
    # - If our HP is low, we must secure water: bid closer to highest_prev_bid.
    # - If our HP is healthy, bid enough to stay competitive but avoid overpaying.
    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Determine target bid baseline from yesterday.
    # Use a slight undercut vs highest to avoid paying too much, unless HP is critical.
    critical = (hp <= 2.0) or (no_water_days >= 2)
    if critical:
        target = highest_prev_bid * 0.98 + 1.0
    else:
        # If others were bidding very high, still try to stay near but not exceed too much.
        if highest_prev_bid >= DAILY_SALARY * 1.1:
            target = second_prev_bid * 0.95 + 3.0
        else:
            target = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.85)

    # Adjust by supply pressure.
    target = target * supply_mult

    # Cap by what we can afford.
    bid = min(budget, target)

    # Ensure we bid at least enough to matter when we have budget.
    min_reasonable = DAILY_SALARY * 0.35
    if bid < min_reasonable and budget >= min_reasonable:
        bid = min_reasonable

    # If budget is tiny, just spend what we can.
    if budget <= 0:
        return 0.0

    return float(max(0.0, bid))
